#include <iostream>
#include <vector>
#include <queue>
#include <string>
using namespace std;

vector<int> adj_list[2020];
int grid_distance[20][20], grid_scan[20][20], grid_pattern_count[20][20];
char grid_char[20][20], pattern_char[20][20];
int dist_grid[20][20];
int delta_x[4]={0,1,-1,0};
int delta_y[4]={1,0,0,-1};
vector<int> node_positions[20][20], node_patterns[20][20];

void connect_nodes(int a, int b) {
    adj_list[a].push_back(b);
    adj_list[b].push_back(a);
}

int dist_map[2020], parent_node[2020], total_sp, total_pp;

bool build_level_graph() {
    queue<int> q;
    for (int i=1; i<=total_sp; i++) {
        if (parent_node[i]==0) {
            dist_map[i]=0;
            q.push(i);
        } else {
            dist_map[i]=3010;
        }
    }
    dist_map[0]=3010;
    while (!q.empty()) {
        int u=q.front(); q.pop();
        if (dist_map[u]<dist_map[0]) {
            for (int v_idx=0; v_idx<(int)adj_list[u].size(); v_idx++) {
                int v=parent_node[adj_list[u][v_idx]];
                if (dist_map[v]>dist_map[u]+1) {
                    dist_map[v]=dist_map[u]+1;
                    q.push(v);
                }
            }
        }
    }
    return dist_map[0]!=3010;
}

bool find_aug_path(int x) {
    if (x==0) return true;
    for (int i=0; i<(int)adj_list[x].size(); i++) {
        int u=parent_node[adj_list[x][i]];
        if (dist_map[u]==dist_map[x]+1) {
            if (find_aug_path(u)) {
                parent_node[x]=adj_list[x][i];
                parent_node[adj_list[x][i]]=x;
                return true;
            }
        }
    }
    return false;
}

int compute_max_matching() {
    int total=0;
    while (build_level_graph()) {
        for (int i=1; i<=total_sp; i++) {
            if (parent_node[i]==0)
                total+=find_aug_path(i);
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            grid_distance[i][j]=t;
    for (int i=1; i<=n; i++)
        cin >> grid_char[i]+1;
    for (int i=1; i<=n; i++)
        cin >> pattern_char[i]+1;
    int rx, ry;
    total_sp=1; total_pp=1000;
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (grid_char[i][j]=='Z'||grid_char[i][j]=='Y') {
                grid_scan[i][j]=-1; grid_distance[i][j]=0;
            }
            if (grid_char[i][j]=='Z') {
                rx=i; ry=j; grid_distance[i][j]=0;
            }
            if ('0'<=grid_char[i][j] && grid_char[i][j]<='9') {
                grid_scan[i][j]=grid_char[i][j]-'0';
            }
            for (int k=0; k<grid_scan[i][j]; k++)
                node_positions[i][j].push_back(total_sp++);
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if ('0'<=pattern_char[i][j] && pattern_char[i][j]<='9') {
                grid_pattern_count[i][j]=pattern_char[i][j]-'0';
            }
            for (int k=0; k<grid_pattern_count[i][j]; k++)
                node_patterns[i][j].push_back(total_pp++);
        }
    }
    queue<pair<int,int>> q;
    q.push({rx,ry});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        for (int d=0; d<4; d++) {
            int nx=x+delta_x[d], ny=y+delta_y[d];
            if (grid_distance[nx][ny]>grid_distance[x][y]+1 && grid_scan[nx][ny]!=-1) {
                grid_distance[nx][ny]=grid_distance[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (grid_scan[i][j]>0) {
                process_point(i,j);
            }
        }
    }
    cout << compute_max_matching() << "\n";
}
